+            match next_action(
+                Utc::now(),
+                resume_at,
+                kick.exists(),
+                q.resumes,
+                renv.max_resumes,
+            ) {
+                AlarmAction::Sleep(d) => std::thread::sleep(d),
+                AlarmAction::Resume => {
+                    let _ = std::fs::remove_file(&kick);
+                    break;
+                }
+                AlarmAction::GiveUp => {
+                    let mut er = rec.clone();
+                    if let Some(qq) = er.quota.as_mut() {
