+pub fn run(mut o: Options) -> i32 {
+    if o.status || o.wait {
+        return detach::query(&o);
+    }
+    if !o.detach_id.trim().is_empty() {
+        return detach::background(&o);
+    }
+    if o.task.trim().is_empty() {
